import { Tour, type TourFinishDetail, type TourSkipDetail } from '@absoluteui/components/tour';

const search = document.createElement('input');
search.id = 'global-search';
search.setAttribute('aria-label', 'Search');
const start = document.createElement('button');
start.type = 'button';
start.textContent = 'Take the tour';
const host = document.createElement('div');
document.body.append(search, start, host);
const tour = Tour.create(host, {
  steps: [
    { id: 'welcome', title: 'Welcome to PeopleHub', content: 'A one-minute tour of the dashboard.' },
    { id: 'search', title: 'Search', content: 'Find people, documents, and pages.', target: '#global-search' },
    { id: 'help', title: 'Help', content: 'Restart this tour from the Help menu.', target: '#help-menu' },
  ],
  dots: true,
});
host.addEventListener('aui-finish', (event) => {
  host.dataset.completed = String((event as CustomEvent<TourFinishDetail>).detail.completed);
});
host.addEventListener('aui-skip', (event) => {
  host.dataset.skippedAt = (event as CustomEvent<TourSkipDetail>).detail.stepId;
});
start.addEventListener('click', () => {
  void tour.start();
});

import { Tour, type TourStepMissingDetail } from '@absoluteui/components/tour';

const panel = document.createElement('details');
const summary = document.createElement('summary');
summary.textContent = 'Filters';
const button = document.createElement('button');
button.textContent = 'Apply';
panel.append(summary, button);
const host = document.createElement('div');
document.body.append(panel, host);
const tour = Tour.create(host, {
  modal: true,
  steps: [
    {
      id: 'apply',
      title: 'Apply filters',
      content: 'Your filters take effect when you apply them.',
      target: () => button,
      placement: 'right',
      onBeforeShow: () => {
        panel.open = true;
      },
    },
  ],
});
host.addEventListener('aui-step-missing', (event) => {
  host.dataset.missing = (event as CustomEvent<TourStepMissingDetail>).detail.reason;
});
void tour.start();
